// intent: Verify binary values with UUID (0x04) or MD5 (0x03) subtypes handle correctly alongside old binary subtype.
#include <nlohmann/json.hpp>
#include <iostream>

int main() {
    try {
        nlohmann::json j;
        std::vector<std::uint8_t> payload(16, 0xAA);
        j["uuid"] = nlohmann::json::binary(payload, 0x04);
        
        auto bson_data = nlohmann::json::to_bson(j);
        auto j_back = nlohmann::json::from_bson(bson_data);
        
        std::cout << "UUID subtype: " << static_cast<int>(j_back["uuid"].get_binary().subtype()) << std::endl;
        std::cout << "UUID size: " << j_back["uuid"].get_binary().size() << std::endl;
    } catch (const std::exception& e) {
        std::cout << "Exception: " << e.what() << std::endl;
    }
}
